// =========================
// Templates exclusivos por condomínio
// (tem prioridade sobre o template enviado pela plataforma)
// =========================
const TEMPLATES_POR_CONDOMINIO = {
  // Residencial Jardim das Flores
  'a2584698-7779-4c7d-8ed4-1b41982f7c27': '1NjG6nLwqqYzYA7Mdv5XHixqhXmJsByKVyakL_zAm6Rk',
};

const TEMPLATE_PADRAO = '1SGUBZEgYR3wGZkzjYpxCv-QU0t52-AN1vD3YscB5g-Y';

// Detecta origem dos dados
const input = $input.first().json;

const veioDoWebhook = !!input.body;

function formatarData(data) {

  if (!data) return '';

  const limpa = data.split('T')[0];

  const [ano, mes, dia] = limpa.split('-');

  return `${dia}/${mes}/${ano}`;
}

// =========================
// Formata endereço ReceitaWS
// =========================
function montarEnderecoReceita(receita) {

  if (!receita) return '';

  const logradouro = receita.logradouro || '';
  const numero = receita.numero || '';
  const complemento = receita.complemento
    ? ' - ' + receita.complemento
    : '';

  const bairro = receita.bairro || '';
  const municipio = receita.municipio || '';

  const uf = (receita.uf || '').toUpperCase();

  const cep = (receita.cep || '')
    .replace(/\D/g, '')
    .replace(/(\d{5})(\d{3})/, '$1-$2');

  const titleCase = (str) =>
    str
      .toLowerCase()
      .replace(/\b[a-zà-ú]/gi, (c) => c.toUpperCase());

  return `${titleCase(logradouro)}, ${numero}${complemento}, ${titleCase(bairro)}, ${titleCase(municipio)}, ${uf}, ${cep}`;
}

// =========================
// Busca endereço via ReceitaWS
// =========================
async function buscarEnderecoPorCNPJ(cnpj) {
  if (!cnpj) {
    return '';
  }

  try {

    const cnpjLimpo = cnpj.replace(/\D/g, '');

    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://www.receitaws.com.br/v1/cnpj/${cnpjLimpo}`,
      json: true
    });

    return montarEnderecoReceita(response);

  } catch (e) {

    return '';
  }
}

// =========================
// Busca cidade/UF via CNPJ
// =========================
async function buscarCidadePorCNPJ(cnpj) {
  if (!cnpj) {
    return '';
  }

  try {

    const cnpjLimpo = cnpj.replace(/\D/g, '');

    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://www.receitaws.com.br/v1/cnpj/${cnpjLimpo}`,
      json: true
    });

    const municipio = response.municipio || '';
    const uf = (response.uf || '').toUpperCase();

    if (!municipio || !uf) {
      return '';
    }

    return `${municipio}/${uf}`;

  } catch (e) {

    return '';
  }
}

// =========================
// Busca cidade/UF via endereço
// =========================
async function buscarCidadePorEndereco(endereco) {

  if (!endereco) {
    return '';
  }

  try {

    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://nominatim.openstreetmap.org/search',
      qs: {
        q: endereco,
        format: 'jsonv2',
        limit: 1,
        addressdetails: 1
      },
      headers: {
        'User-Agent': 'n8n'
      },
      json: true
    });

    if (!response.length) {
      return '';
    }

    const address = response[0].address || {};

    const cidade =
      address.city ||
      address.town ||
      address.village ||
      address.municipality ||
      '';

    const uf =
      address.state_code ||
      address.state ||
      '';

    if (!cidade) {
      return '';
    }

    return uf ? `${cidade}/${uf}` : cidade;

  } catch (e) {

    return '';
  }
}

function gerarDataSubmissao() {

  const meses = [
    'Janeiro',
    'Fevereiro',
    'Março',
    'Abril',
    'Maio',
    'Junho',
    'Julho',
    'Agosto',
    'Setembro',
    'Outubro',
    'Novembro',
    'Dezembro'
  ];

  const hoje = new Date();

  const dia = hoje.getDate();
  const mes = meses[hoje.getMonth()];
  const ano = hoje.getFullYear();

  return `${dia} de ${mes} de ${ano}`;
}

function obterPrazo(tipo, dias) {

  switch (tipo) {

    case 'sem_prazo':
      return '';

    case 'imediato':
      return 'Imediato';

    case 'dias':
      return dias ? String(dias) : '';

    default:
      return '';
  }
}

const dataSubmissao = gerarDataSubmissao();

let output = {};

if (veioDoWebhook) {

  // =========================
  // WEBHOOK / PLATAFORMA
  // =========================

  const body = input.body;

  const placeholders = body.placeholders || {};

  const prazo = obterPrazo(
    placeholders.prazo_tipo,
    placeholders.prazo_dias
  );

  let endereco = placeholders.endereco_condominio || '';

  let cidade = '';

  // Busca via CNPJ se endereço vazio
  if (!endereco && placeholders.numero_cnpj) {

    endereco = await buscarEnderecoPorCNPJ.call(
      this,
      placeholders.numero_cnpj
    );
  }
  if (placeholders.numero_cnpj) {

    cidade = await buscarCidadePorCNPJ.call(
      this,
      placeholders.numero_cnpj
    );

  } else if (endereco) {

    cidade = await buscarCidadePorEndereco.call(
      this,
      endereco
    );
  }

  output = {

    origem: 'Plataforma',

    cidade: cidade,

    data_submissao: dataSubmissao,

    prazo: prazo,

    id_condomino: body.condomino.id || '',

    numero_bloco: placeholders.numero_bloco || '',

    numero_unidade: placeholders.numero_unidade || '',

    data_infracao: formatarData(placeholders.data_infracao),

    foto_infracao: placeholders.foto_infracao || '',

    foto_infracao_2: placeholders.foto_infracao_2 || '',

    id_condominio: body.condominio.id || '',

    nome_condominio: placeholders.nome_condominio || '',

    numero_cnpj: placeholders.numero_cnpj || '',

    nome_sindico: placeholders.nome_sindico
      ? `${placeholders.nome_sindico} - síndico`
      : '',

    assinatura_sindico:
      placeholders.assinatura || null,

    logo_condominio: placeholders.logo_condominio || '',

    endereco_condominio: endereco,

    infracao: placeholders.infracao || '',

    template_corpo:
      TEMPLATES_POR_CONDOMINIO[body.condominio.id] ||
      body.template_corpo ||
      TEMPLATE_PADRAO
  };

} else {

  // =========================
  // N8N / OUTRO WORKFLOW
  // =========================

  const dadosCadastro = input;
  const dadosNotificacao = $('Trata os dados').first().json;

  let endereco = dadosCadastro.condominio_endereco || '';

  const prazo = obterPrazo(
    dadosNotificacao.prazo_tipo,
    dadosNotificacao.prazo_dias
  );

  let cidade = '';

  // Busca via CNPJ se endereço vazio
  if (!endereco && dadosCadastro.condominio_cnpj) {
    endereco = await buscarEnderecoPorCNPJ.call(
      this,
      dadosCadastro.condominio_cnpj
    );
  }

  if (dadosCadastro.condominio_cnpj) {

    cidade = await buscarCidadePorCNPJ.call(
      this,
      dadosCadastro.condominio_cnpj
    );

  } else if (endereco) {

    cidade = await buscarCidadePorEndereco.call(
      this,
      endereco
    );
  }

  output = {

    origem: 'N8N',

    cidade: cidade,

    data_submissao: dataSubmissao,

    prazo: prazo,

    id_condomino:
      dadosCadastro.condomino_id || '',

    numero_bloco:
      dadosNotificacao.bloco || '',

    numero_unidade:
      dadosNotificacao.unidade || '',

    data_infracao: formatarData(
      dadosNotificacao.data_infracao
    ),

    foto_infracao:
      dadosNotificacao.foto_infracao_path || '',

    foto_infracao_2:
      dadosNotificacao.foto_infracao_path_2 || '',

    id_condominio:
      dadosCadastro.condominio_id || '',

    nome_condominio:
      dadosCadastro.condominio_nome || '',

    numero_cnpj:
      dadosCadastro.condominio_cnpj || '',

    nome_sindico:
      dadosCadastro.condominio_sindico_nome
        ? `${dadosCadastro.condominio_sindico_nome} - síndico`
        : '',

    assinatura_sindico:
      dadosCadastro.condominio_sindico_assinatura || null,

    logo_condominio:
      dadosCadastro.condominio_logo_url || '',

    endereco_condominio:
      endereco,

    infracao:
      dadosNotificacao.infracao || '',

    template_corpo:
      TEMPLATES_POR_CONDOMINIO[dadosCadastro.condominio_id] ||
      TEMPLATE_PADRAO
  };
}

return [
  {
    json: output
  }
];

